<?php
require_once __DIR__ . '/config/database.php';require_once __DIR__ . '/config/app.php';require_once __DIR__ . '/includes/payments.php';
require_login('student');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method not allowed.');}verify_csrf();
$courseId=filter_var($_POST['course_id']??null,FILTER_VALIDATE_INT);$provider=$_POST['provider']??'';$phone=preg_replace('/\D+/','',(string)($_POST['phone']??''));
if(!$courseId||!in_array($provider,['paystack','mpesa'],true)){flash('Choose a course and payment method.','error');redirect('courses.php');}
$q=$pdo->prepare("SELECT id,title FROM courses WHERE id=? AND status='active'");$q->execute([$courseId]);$course=$q->fetch();if(!$course){flash('This course is no longer available.','error');redirect('courses.php');}
$q=$pdo->prepare('SELECT id FROM enrollments WHERE user_id=? AND course_id=?');$q->execute([current_user()['id'],$courseId]);if($q->fetch()){flash('You are already enrolled in this course.');redirect('student/learning.php');}
if($provider==='mpesa'){if(preg_match('/^0[17]\d{8}$/',$phone))$phone='254'.substr($phone,1);elseif(preg_match('/^[17]\d{8}$/',$phone))$phone='254'.$phone;if(!preg_match('/^254[17]\d{8}$/',$phone)){flash('Enter a valid Kenyan mobile number for M-Pesa.','error');redirect('student/dashboard.php?course='.$courseId);}}
$reference='WIS-'.strtoupper(bin2hex(random_bytes(10)));$pdo->prepare('INSERT INTO payments(user_id,course_id,provider,reference,amount_kes,phone) VALUES(?,?,?,?,5.00,?)')->execute([current_user()['id'],$courseId,$provider,$reference,$provider==='mpesa'?$phone:null]);
if($provider==='paystack'){
    $secret=env_value('PAYSTACK_SECRET_KEY');if($secret===''||str_contains($secret,'replace_me')){payment_fail($pdo,$reference,'Paystack is not configured');flash('Paystack is not configured. Set PAYSTACK_SECRET_KEY in .env.','error');redirect('student/dashboard.php?course='.$courseId);}
    $ch=curl_init('https://api.paystack.co/transaction/initialize');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$secret,'Content-Type: application/json'],CURLOPT_POSTFIELDS=>json_encode(['email'=>current_user()['email'],'amount'=>500,'currency'=>'KES','reference'=>$reference,'callback_url'=>app_url('callbacks/paystack.php')]),CURLOPT_TIMEOUT=>25]);$raw=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$err=curl_error($ch);curl_close($ch);$data=json_decode((string)$raw,true);
    if($status<200||$status>=300||empty($data['data']['authorization_url'])){error_log('Paystack initialize: '.$err.' '.$raw);payment_fail($pdo,$reference,'Paystack initialization failed');flash('Paystack could not start the payment. Check your sandbox credentials and try again.','error');redirect('student/dashboard.php?course='.$courseId);}header('Location: '.$data['data']['authorization_url']);exit;
}
$key=env_value('MPESA_CONSUMER_KEY');$secret=env_value('MPESA_CONSUMER_SECRET');$shortcode=env_value('MPESA_SHORTCODE');$passkey=env_value('MPESA_PASSKEY');$callback=env_value('MPESA_CALLBACK_URL');
if(!$key||!$secret||!$shortcode||!$passkey||!$callback||str_contains($key,'replace_me')){payment_fail($pdo,$reference,'M-Pesa is not configured');flash('M-Pesa is not configured. Add Daraja sandbox keys and a public ngrok callback URL to .env.','error');redirect('student/dashboard.php?course='.$courseId);}
$base=env_value('MPESA_ENV','sandbox')==='production'?'https://api.safaricom.co.ke':'https://sandbox.safaricom.co.ke';$ch=curl_init($base.'/oauth/v1/generate?grant_type=client_credentials');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_USERPWD=>$key.':'.$secret,CURLOPT_TIMEOUT=>20]);$tokenRaw=curl_exec($ch);$tokenCode=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$token=json_decode((string)$tokenRaw,true)['access_token']??'';
if(!$token||$tokenCode>=300){payment_fail($pdo,$reference,'M-Pesa authentication failed');flash('M-Pesa could not connect. Check your Daraja sandbox credentials.','error');redirect('student/dashboard.php?course='.$courseId);}
$timestamp=date('YmdHis');$password=base64_encode($shortcode.$passkey.$timestamp);$payload=['BusinessShortCode'=>$shortcode,'Password'=>$password,'Timestamp'=>$timestamp,'TransactionType'=>env_value('MPESA_TRANSACTION_TYPE','CustomerPayBillOnline'),'Amount'=>5,'PartyA'=>$phone,'PartyB'=>$shortcode,'PhoneNumber'=>$phone,'CallBackURL'=>$callback,'AccountReference'=>$reference,'TransactionDesc'=>'Warwa course enrollment'];
$ch=curl_init($base.'/mpesa/stkpush/v1/processrequest');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$token,'Content-Type: application/json'],CURLOPT_POSTFIELDS=>json_encode($payload),CURLOPT_TIMEOUT=>25]);$raw=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$data=json_decode((string)$raw,true);
if($status<200||$status>=300||empty($data['CheckoutRequestID'])){payment_fail($pdo,$reference,'M-Pesa STK push failed');error_log('M-Pesa STK: '.$raw);flash('M-Pesa could not send the payment prompt. Check the number and try again.','error');redirect('student/dashboard.php?course='.$courseId);}
$pdo->prepare("UPDATE payments SET provider_reference=? WHERE reference=? AND status='pending'")->execute([$data['CheckoutRequestID'],$reference]);flash('M-Pesa prompt sent. Approve KSh 5 on your phone; Safaricom will confirm the result.');redirect('student/payments.php');
